// Generated by build-embedded-archives.mjs from the shared name rule sources.
(() => {
"use strict";
// Shared source for React titles and independently rendered archive documents.
// Name labels use these seams; Japanese prose keeps its normal kinsoku.
const SEAM = "\u200b";
const LEADING_WORD = /^(仮面ライダー|ロード(?=[\u30a0-\u30ff]{3}))(?=.)/u;
const SAGA_WORD = /([\u30a0-\u30ff]{3,})(サーガ)(?=$|[・／/\s（(])/gu;

/** @param {string} name */
function withWordBreaks(name) {
  return name
    .replace(LEADING_WORD, `$1${SEAM}`)
    .replace(SAGA_WORD, `$1${SEAM}$2`)
    .replace(/([・／/])(?=.)/gu, `$1${SEAM}`)
    .replace(/(サーガ)(\s+)(?=\S)/gu, `$1$2${SEAM}`);
}

/** @param {string} name @returns {{ text: string, protected: boolean }[]} */
function nameWords(name) {
  return withWordBreaks(name)
    .split(SEAM)
    .filter(Boolean)
    .map((text) => ({
      text,
      // Short words stay whole. Long unseamed names retain a narrow-column
      // fallback without smaller type or a wider page.
      protected: [...text.trim()].length <= 4,
    }));
}


// The archive is a separate document. Enhance only display labels after its
// existing catalogue revision, leaving specs, prose, inputs and records alone.
function enhanceNames() {
  document
    .querySelectorAll("h1, h2, h3, h4, button, label, .rexonance-setting-hero > p")
    .forEach((label) => {
      const walker = document.createTreeWalker(label, NodeFilter.SHOW_TEXT);
      const nodes = [];
      while (walker.nextNode()) {
        if (!walker.currentNode.parentElement.closest(".name-word")) nodes.push(walker.currentNode);
      }
      nodes.forEach((node) => {
        const value = node.textContent;
        const matches = [
          ...value.matchAll(
            /(?:仮面ライダー)?[\u30a0-\u30ff]*サーガ(?:[・ ](?:ウルトラ|マックス))?/gu,
          ),
        ];
        if (!matches.length) return;
        const fragment = document.createDocumentFragment();
        let cursor = 0;
        matches.forEach((match) => {
          fragment.append(value.slice(cursor, match.index));
          nameWords(match[0]).forEach((word, index) => {
            if (index) fragment.append(document.createElement("wbr"));
            const span = document.createElement("span");
            span.className = `name-word${word.protected ? " name-word--protected" : ""}`;
            span.textContent = word.text;
            fragment.append(span);
          });
          cursor = match.index + match[0].length;
        });
        fragment.append(value.slice(cursor));
        node.replaceWith(fragment);
      });
    });
  // Existing geometry sync measures the new labels; no row or artwork sizes
  // are changed here, and no polling/scroll listener is added.
  window.ArchiveComparisonUI?.refresh();
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", () => requestAnimationFrame(enhanceNames), { once: true });
} else {
  requestAnimationFrame(enhanceNames);
}

})();
